// Generated by `pnpm nx g @app/generators:action messages.publish`. Requests go through the real router
// with createTestEngine().inject. They fail until createMessagesPublishAction is implemented; do not weaken them.
import { messagesPublish } from '@app/contracts';
import { createRoleAuthorizer, type ExecutorWrite } from '@app/kernel';
import { mintConfirmedCopyProof, type ConnectionManager } from '@app/ports';
import {
  createMessagesPublishAction,
  createMessagesFakeDeps,
} from '@app/svc-messages';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

/** A manager whose one lease confirms every copy; the testkit may build leases and their proofs. */
const writes = (): ExecutorWrite => {
  const unused = (): never => {
    throw new Error('this spec takes a publish lease only');
  };
  const connections: ConnectionManager = {
    peek: unused,
    source: unused,
    observe: unused,
    budget: unused,
    usage: unused,
    publish: () =>
      Promise.resolve({
        publish: () =>
          Promise.resolve({
            outcome: 'confirmed' as const,
            proof: mintConfirmedCopyProof({
              destination: 'orders',
              confirmedAt: 1,
            }),
          }),
        blocked: () => false,
        release: () => Promise.resolve(),
      }),
  };
  return { mgmt: {} as ExecutorWrite['mgmt'], connections };
};

const message = {
  vhost: '/',
  exchange: '',
  routingKey: 'orders',
  props: { contentType: 'text/plain' },
  body: { encoding: 'utf8', data: 'hello' },
};

const subject = () => createMessagesPublishAction(createMessagesFakeDeps());
const def = messagesPublish;
const KEY = 'generated-spec-key-0001';
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('POST /connections/{cid}/messages/publish', () => {
  it('route 1: the route runs messages.publish and answers in the shape of the contract', async () => {
    engine = createTestEngine({ actions: [subject()], writes: writes() });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'POST',
      path: '/connections/c1/messages/publish',
      payload: message,
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
    expect(answer.json()).toMatchObject({
      allConfirmed: true,
      copies: [{ index: 0, outcome: 'confirmed' }],
    });
  });

  it('route 2: a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'POST',
      path: '/connections/c1/messages/publish',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('route 3: a caller that does not hold messages.publish gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'POST',
      path: '/connections/c1/messages/publish',
      payload: message,
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('route 4: input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'POST',
      path: '/connections/c1/messages/publish',
      payload: { ...message, mandatory: false },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('route 5: another method on the same path is 405', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('POST');
  });
});
